/**
 * User/Profile Routes — Profile management, addresses, order history.
 * Generated by BackendForge
 */
const express = require('express');
const router = express.Router();
const userController = require('../controllers/user.controller');
const { authenticate } = require('../middleware/auth.middleware');
const { validate, schemas } = require('../middleware/validator.middleware');

router.use(authenticate);

// Profile
router.get('/profile', userController.getProfile);
router.put('/profile', validate(schemas.updateProfile), userController.updateProfile);

// Addresses
router.get('/addresses', userController.getAddresses);
router.post('/addresses', userController.addAddress);
router.put('/addresses/:addressId', userController.updateAddress);
router.delete('/addresses/:addressId', userController.deleteAddress);

// Order history (customer's own orders with real-time status)
router.get('/orders', userController.getMyOrders);

module.exports = router;
